function _wrapWithChildren(kind: string, children: readonly unknown[]): unknown {
	switch (kind) {
		case 'translation_unit':
			return (coerceToTranslationUnit as (...args: unknown[]) => unknown)(...children);
		case 'preproc_params':
			return (coerceToPreprocParams as (...args: unknown[]) => unknown)(...children);
		case 'preproc_else':
			return (coerceToPreprocElse as (...args: unknown[]) => unknown)(...children);
		case 'preproc_else_in_field_declaration_list':
			return (coerceToPreprocElseInFieldDeclarationList as (...args: unknown[]) => unknown)(...children);
		case 'preproc_else_in_enumerator_list':
			return (coerceToPreprocElseInEnumeratorList as (...args: unknown[]) => unknown)(...children);
		case 'preproc_else_in_enumerator_list_no_comma':
			return (coerceToPreprocElseInEnumeratorListNoComma as (...args: unknown[]) => unknown)(...children);
		case 'preproc_parenthesized_expression':
			return F.buildPreprocParenthesizedExpression(
				children[0] as Parameters<typeof F.buildPreprocParenthesizedExpression>[0]
			);
		case 'preproc_defined':
			return F.buildPreprocDefined(children[0] as Parameters<typeof F.buildPreprocDefined>[0]);
		case 'preproc_argument_list':
			return (coerceToPreprocArgumentList as (...args: unknown[]) => unknown)(...children);
		case 'attribute_declaration':
			return (coerceToAttributeDeclaration as (...args: unknown[]) => unknown)(...children);
		case 'ms_declspec_modifier':
			return F.buildMsDeclspecModifier(children[0] as Parameters<typeof F.buildMsDeclspecModifier>[0]);
		case 'ms_based_modifier':
			return F.buildMsBasedModifier(children[0] as Parameters<typeof F.buildMsBasedModifier>[0]);
		case 'ms_pointer_modifier':
			return F.buildMsPointerModifier(children[0] as Parameters<typeof F.buildMsPointerModifier>[0]);
		case 'declaration_list':
			return (coerceToDeclarationList as (...args: unknown[]) => unknown)(...children);
		case 'compound_statement':
			return (coerceToCompoundStatement as (...args: unknown[]) => unknown)(...children);
		case 'type_qualifier':
			return F.buildTypeQualifier(children[0] as Parameters<typeof F.buildTypeQualifier>[0]);
		case 'field_declaration_list':
			return (coerceToFieldDeclarationList as (...args: unknown[]) => unknown)(...children);
		case 'bitfield_clause':
			return F.buildBitfieldClause(children[0] as Parameters<typeof F.buildBitfieldClause>[0]);
		case 'old_style_parameter_list':
			return (coerceToOldStyleParameterList as (...args: unknown[]) => unknown)(...children);
		case 'top_level_expression_statement':
			return F.buildTopLevelExpressionStatement(
				children[0] as Parameters<typeof F.buildTopLevelExpressionStatement>[0]
			);
		case 'expression_statement':
			return F.buildExpressionStatement(children[0] as Parameters<typeof F.buildExpressionStatement>[0]);
		case 'else_clause':
			return F.buildElseClause(children[0] as Parameters<typeof F.buildElseClause>[0]);
		case 'return_statement':
			return F.buildReturnStatement(children[0] as Parameters<typeof F.buildReturnStatement>[0]);
		case 'goto_statement':
			return F.buildGotoStatement(children[0] as Parameters<typeof F.buildGotoStatement>[0]);
		case 'seh_finally_clause':
			return F.buildSehFinallyClause(children[0] as Parameters<typeof F.buildSehFinallyClause>[0]);
		case 'update_expression':
			return F.buildUpdateExpression(children[0] as Parameters<typeof F.buildUpdateExpression>[0]);
		case 'gnu_asm_output_operand_list':
			return (coerceToGnuAsmOutputOperandList as (...args: unknown[]) => unknown)(...children);
		case 'gnu_asm_input_operand_list':
			return (coerceToGnuAsmInputOperandList as (...args: unknown[]) => unknown)(...children);
		case 'gnu_asm_clobber_list':
			return (coerceToGnuAsmClobberList as (...args: unknown[]) => unknown)(...children);
		case 'gnu_asm_goto_list':
			return (coerceToGnuAsmGotoList as (...args: unknown[]) => unknown)(...children);
		case 'extension_expression':
			return F.buildExtensionExpression(children[0] as Parameters<typeof F.buildExtensionExpression>[0]);
		case 'argument_list':
			return (coerceToArgumentList as (...args: unknown[]) => unknown)(...children);
		case 'parenthesized_expression':
			return F.buildParenthesizedExpression(children[0] as Parameters<typeof F.buildParenthesizedExpression>[0]);
		case 'initializer_list':
			return F.buildInitializerList(children[0] as Parameters<typeof F.buildInitializerList>[0]);
		case 'initializer_pair':
			return F.buildInitializerPair(children[0] as Parameters<typeof F.buildInitializerPair>[0]);
		case 'subscript_designator':
			return F.buildSubscriptDesignator(children[0] as Parameters<typeof F.buildSubscriptDesignator>[0]);
		case 'field_designator':
			return F.buildFieldDesignator(children[0] as Parameters<typeof F.buildFieldDesignator>[0]);
		case 'initializer_list_elements':
			return (coerceToInitializerListElements as (...args: unknown[]) => unknown)(...children);
		case 'enumerator_list_group':
			return F.buildEnumeratorListGroup(children[0] as Parameters<typeof F.buildEnumeratorListGroup>[0]);
		case 'field_identifier':
			return F.buildFieldIdentifier(children[0] as Parameters<typeof F.buildFieldIdentifier>[0]);
		case 'type_identifier':
			return F.buildTypeIdentifier(children[0] as Parameters<typeof F.buildTypeIdentifier>[0]);
		case 'statement_identifier':
			return F.buildStatementIdentifier(children[0] as Parameters<typeof F.buildStatementIdentifier>[0]);
		default:
			return undefined;
	}
}

function _wrapArray<T>(kind: string, arr: readonly unknown[]): Admit<T> {
	const elementKind = _wrapElementKinds[kind];
	if (_wrapDirectKinds.has(kind) && elementKind !== undefined && elementKind in _wrapKindIds) {
		if (arr.length === 0 && _wrapOptionalSoleKinds.has(kind)) return _wrapWithChildren(kind, []) as Admit<T>;
		return _wrapWithChildren(kind, [_wrapArray(elementKind, arr)]) as Admit<T>;
	}
	return _wrapWithChildren(kind, arr) as Admit<T>;
}

function _resolveOneBranch<T>(
	v: _LooseFieldInput,
	kind: string,
	altKinds?: readonly (string | number)[],
	optionalSlot?: boolean
): Admit<T> {
	if (v === undefined || v === null) return v as Admit<T>;
	if (optionalSlot === true && Array.isArray(v) && v.length === 0) return undefined as Admit<T>;
	const tagged = _splitTag(v);
	if (tagged !== undefined) {
		const kn = _fromOfTag(tagged.tag, [kind]);
		if (kn !== kind && kind in _wrapKindIds)
			return _resolveOneBranch<T>(_resolveByKind(kn, tagged.rest), kind, altKinds);
	}
	if (isNodeValue(v)) {
		const wrapId = _wrapKindIds[kind];
		if (wrapId !== undefined && v.$type !== wrapId) {
			if (altKinds !== undefined && altKinds.some((k) => k === v.$type)) return v as Admit<T>;
			return _wrapWithChildren(kind, [v]) as Admit<T>;
		}
		return v as Admit<T>;
	}
	if (Array.isArray(v) && kind in _wrapKindIds) {
		return _wrapArray(kind, v) as Admit<T>;
	}
	if ((typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean') && _isFromKind(kind)) {
		return _resolveByKind(kind, v) as Admit<T>;
	}
	if (typeof v === 'object' && !Array.isArray(v)) {
		const tagged = _splitTag(v);
		if (tagged !== undefined) return _resolveByKind(_fromOfTag(tagged.tag, [kind]), tagged.rest) as Admit<T>;
		if (_isFromKind(kind)) return _resolveByKind(kind, v) as Admit<T>;
	}
	if (typeof v === 'object') {
		throw new Error(`_resolveOneBranch: cannot resolve value to branch kind '${kind}': ${JSON.stringify(v)}`);
	}
	return v as Admit<T>;
}

function _resolveManyLeaf<T>(v: _LooseFieldInput, kind: string): readonly Admit<T>[] {
	if (v === undefined || v === null) return [];
	const arr: readonly _LooseFieldInput[] = Array.isArray(v) ? v : [v];
	return arr.map((e) => _resolveOneLeaf<T>(e, kind));
}

function _resolveManyBranch<T>(
	v: _LooseFieldInput,
	kind: string,
	altKinds?: readonly (string | number)[]
): readonly Admit<T>[] {
	if (v === undefined || v === null) return [];
	const arr: readonly _LooseFieldInput[] = Array.isArray(v) ? v : [v];
	return arr.map((e) => _resolveOneBranch<T>(e, kind, altKinds));
}

function _resolveBooleanKeyword<T>(v: _LooseFieldInput): T {
	if (v === undefined || v === null) return v as T;
	if (v === true || v === false) return v as T;
	if (typeof v === 'string') return true as T;
	if (isNodeValue(v)) return v as T;
	if (Array.isArray(v)) return v as T;
	return v as T;
}

function _resolveBitflag<T>(v: _LooseFieldInput): T {
	if (v === undefined || v === null) return v as T;
	if (typeof v === 'number') return v as T;
	if (typeof v === 'string') return v as T;
	if (Array.isArray(v)) return v as T;
	if (isNodeValue(v)) return v as T;
	return v as T;
}

/** Narrows a coercer input to its config arm. A bare `isNodeValue` check
 *  cannot: the UntypedNode arm is not a strict subtype of the config arm, so
 *  negative narrowing leaves it in place. */
function _isLooseConfig<C>(v: C | AnyUntypedNode): v is C {
	return !isNodeValue(v);
}

